"""Original GRE-style quiz questions per topic, with explanations (written for this app).

Question fields: q (text), c (choices), a (index of the answer, or a list of indices for
"select all / select two" questions), x (explanation). QC questions use the four standard choices.
"""

QC = ['Quantity A is greater', 'Quantity B is greater', 'The two quantities are equal',
      'The relationship cannot be determined']


def qc(a, b, ans, x, given=''):
    return dict(q=(given + '\n' if given else '') + f'Quantity A: {a}\nQuantity B: {b}', c=QC, a=ans, x=x)


